// Listado oficial de centros educativos por distrito (código SIGERD, nombre, secciones y matrícula).
// Fuente: SIGERD / MINERD. Los datos se pueden actualizar pegando el nuevo reporte en este archivo.
// El campo `nivel` y los prefijos de nombre ("Liceo", "Escuela Primaria", "Centro Educativo",
// "(Básica de Adultos)") los aplica scripts/aplicar-niveles.js a partir de data/padron-niveles.json.

export interface Centro {
  codigo?: string // Código SIGERD (ej. '00211'). Opcional: centros recién inaugurados sin código.
  nombre: string
  secciones?: number
  matricula?: number
  nivel?: string // Nivel oficial MINERD (ej. 'Inicial - Primaria - Secundaria').
  tanda?: string // Turno (Matutina, Vespertina, Nocturna, Semipresencial).
  periodo?: string // A qué período pertenece la matrícula (ej. '2024-2025').
  sector?: string // Barrio del centro. Viene de data/ubicaciones.ts.
  tipo?: 'Público' | 'Privado' | 'Semioficial'
}

export interface CentrosDistrito {
  codigo: string // Código del distrito (ej. '15-01')
  sigerd: string // Código SIGERD del distrito (ej. '1501')
  nombre: string
  centros: Centro[]
}

